// Tira o texto limpo do e-mail e o primeiro link de matéria (fonte).
const saida = [];
for (const item of $input.all()) {
  const j = item.json;
  const html = j.html || j.textAsHtml || '';
  let texto = j.text || html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
  texto = texto.replace(/&nbsp;/g, ' ').replace(/https?:\/\/\S+/g, ' ').replace(/\s+/g, ' ').trim();
  const links = [...html.matchAll(/href="(https?:[^"]+)"/gi)].map(m => m[1])
    .filter(u => !/unsubscribe|descadastr|mailto|google\.com\/maps|facebook|instagram|twitter|x\.com/i.test(u));
  const titulo = (j.subject || '').replace(/^(fwd?|enc|res|re):\s*/i, '').trim();
  saida.push({ json: {
    titulo,
    texto: texto.slice(0, 12000),
    url: links[0] || '',
    email_id: j.id,
    github_repo: j.github_repo, publicar: j.publicar, privacidade: j.privacidade,
    cenas: j.cenas, voz: j.voz, callback_url: j.callback_url,
  }});
}
return saida;
